const pageContent = document.getElementById("page-content");
const breadcrumbs = document.getElementById("breadcrumbs");
const sidebar = document.getElementById("sidebar");
const pageNames = {home:"Главная",program:"Школьная программа",quests:"Квесты · Исследуй физику",lab:"Виртуальная лаборатория",life:"Физика в жизни",simple:"Объясни просто",tasks:"Решение задач",tests:"Проверка знаний",glossary:"Словарь",progress:"Мой прогресс",lesson:"Урок"};
let currentGrade = 7;
let completed = JSON.parse(localStorage.getItem("impuls-completed") || "[]");

const prismArt = `<div class="prism"><svg viewBox="0 0 300 200"><defs><linearGradient id="pg" x1="0" x2="1" y1="0" y2="1"><stop stop-color="#eafaff" stop-opacity=".9"/><stop offset=".5" stop-color="#397eff" stop-opacity=".25"/><stop offset="1" stop-color="#9c6cff" stop-opacity=".7"/></linearGradient><filter id="glow"><feGaussianBlur stdDeviation="5" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs><path d="M35 120 130 18 235 120Z" fill="url(#pg)" stroke="#a8edff" stroke-width="2.5"/><path d="M130 18 151 120M35 120h200" fill="none" stroke="#8bbdff" stroke-width="1.5"/><path d="M0 120h106l12-17 12 37 15-28 12 8h143" fill="none" stroke="#00d4ff" stroke-width="3" filter="url(#glow)"/><path d="M0 120h106" stroke="#fff" stroke-width="2" opacity=".8"/></svg></div>`;
const featureData = [
 ["program","▤","Школьная программа","Полный курс физики с 7 по 11 класс.","blue"],
 ["quests","✦","Заметь. Почувствуй. Исследуй.","Открывайте невидимые процессы и исследуйте физику вокруг себя.","violet"], ["lab","⚗","Виртуальная лаборатория","Проводите эксперименты и наблюдайте закономерности.","green"],
 ["life","◉","Физика в жизни","Находите физические явления вокруг себя.","green"],
 ["simple","✦","Объясни просто","Разбирайтесь в сложных понятиях понятным языком.","gold"],
 ["tasks","∑","Решение задач","Учитесь рассуждать и решать пошагово.","blue"],
 ["tests","◎","Проверка знаний","Проверяйте себя и закрепляйте материал.","violet"]
];
const gradeTopics = {
  7:["Физика и методы изучения природы","Первоначальные сведения о строении вещества","Взаимодействие тел","Давление твёрдых тел, жидкостей и газов","Работа и мощность. Энергия"],
  8:["Тепловые явления","Изменение агрегатных состояний вещества","Электрические явления","Электромагнитные явления","Световые явления"],
  9:["Законы взаимодействия и движения тел","Механические колебания и волны","Электромагнитное поле","Строение атома и атомного ядра"],
  10:["Механика","Молекулярная физика и термодинамика","Электродинамика"],
  11:["Электродинамика","Колебания и волны","Оптика","Основы специальной теории относительности","Квантовая физика"]
};
function setPage(page){
  if(!pageNames[page]) page="home";
  document.querySelectorAll("[data-page]").forEach(b=>b.classList.toggle("active",b.dataset.page===page));
  breadcrumbs.textContent=pageNames[page];
  closeMobileMenu();
  const renderers={home:homePage,program:programPage,quests:questsPage,lab:labPage,life:lifePage,simple:simplePage,tasks:tasksPage,tests:testsPage,glossary:glossaryPage,progress:progressPage};
  pageContent.innerHTML=(renderers[page]||homePage)();
  pageContent.dataset.page=page;
  if(page==="lab"){updateSimulation();bindMoleculeModel();bindDensityLab();bindForceLab();bindFrictionAndResultant();bindHydrostaticLab();}
  if(page==="program") bindGradeButtons();
  if(page==="simple") document.getElementById("simple-search-btn").addEventListener("click",searchSimple);
  if(page==="tests") bindQuiz();
  if(page==="tasks") bindTask();
  window.scrollTo({top:0,behavior:"smooth"});
}
function homePage(){return `
<section class="hero"><div><div class="eyebrow">Цифровая образовательная платформа · 7–11 классы</div><h1>Физика — это ключ к пониманию мира</h1><p>Изучайте законы природы, проводите виртуальные эксперименты и открывайте физику в привычных вещах — от школьного класса до космоса.</p><div class="hero-actions"><button class="primary-btn" data-go="program">Начать обучение →</button><button class="secondary-btn" data-go="lab">В лабораторию</button></div></div>${prismArt}</section>
<div class="section-head"><div><h2>Выбери свой класс</h2><p>Материалы и темы будут подобраны по программе обучения</p></div></div>
<div class="grade-grid">${[7,8,9,10,11].map(g=>`<button class="grade-card ${g===currentGrade?'selected':''}" data-grade="${g}"><strong>${g}</strong><span>класс</span></button>`).join("")}</div>
<div class="section-head"><div><h2>Исследуй физику</h2><p>Выбери направление и начни открывать новое</p></div></div>
<div class="feature-grid">${featureData.map(f=>`<button class="feature-card ${f[4]}" data-go="${f[0]}"><span class="feature-icon">${f[1]}</span><h3>${f[2]}</h3><p>${f[3]}</p></button>`).join("")}</div>
<div class="progress-panel"><div class="progress-ring"><span>${Math.min(100,Math.round(completed.length/25*100))}%</span></div><div><strong>Мой прогресс</strong><p>Завершено уроков: ${completed.length} · Продолжайте исследование</p></div><button class="secondary-btn" data-go="progress">Подробнее →</button></div>
<div class="section-head"><div><h2>Популярные темы</h2><p>С чего можно начать знакомство с физикой</p></div></div>
<div class="content-grid"><article class="content-card"><span class="tag">Механика</span><h3>Почему движется тело?</h3><p>Разберитесь, как силы изменяют скорость и направление движения.</p><button class="text-link" data-lesson="Законы движения и силы">Открыть тему →</button></article><article class="content-card"><span class="tag">Оптика</span><h3>Как свет меняет направление?</h3><p>Исследуйте отражение, преломление и разложение света.</p><button class="text-link" data-lesson="Свет и оптика">Открыть тему →</button></article><article class="content-card"><span class="tag">Электричество</span><h3>Откуда берётся ток?</h3><p>Познакомьтесь с электрическим зарядом и движением частиц.</p><button class="text-link" data-lesson="Электрический ток">Открыть тему →</button></article></div>`}
function programPage(){
 const gradeSelector=`<div class="section-head"><div><h2>Выбери класс</h2><p>Можно переключаться между классами в любой момент.</p></div></div><div class="grade-grid">${[7,8,9,10,11].map(g=>`<button class="grade-card ${g===currentGrade?'selected':''}" data-grade="${g}" aria-pressed="${g===currentGrade}"><strong>${g}</strong><span>класс</span></button>`).join("")}</div>`;
 if(currentGrade!==7)return `<h1 class="page-title">Школьная программа · ${currentGrade} класс</h1><p class="page-intro">Структура этого класса будет наполнена по рабочей программе выбранной школы. Ты можешь в любой момент вернуться к 7 классу или выбрать другой класс.</p>${gradeSelector}<div class="content-card"><span class="tag">Раздел готовится</span><h2>${currentGrade} класс</h2><p>Сейчас подробно собираем материалы 7 класса. Структуру остальных классов сохраним в едином курсе и наполним после получения рабочих программ.</p><button class="primary-btn" data-grade="7">Перейти к 7 классу</button></div>`;
 const chapters=window.IMPULS_CURRICULUM_7;
 return `<h1 class="page-title">Школьная программа · 7 класс</h1><p class="page-intro">Структура по оглавлению учебника И. М. Перышкина и А. И. Иванова, предоставленному на фотографиях. Учебные часы и календарную последовательность уточним по рабочей программе школы.</p>${gradeSelector}${chapters.map((c,i)=>`<section><div class="section-head"><div><span class="tag">Раздел ${i+1}</span><h2>${c.title}</h2></div></div><div class="lesson-list">${c.items.map((t,j)=>`<div class="lesson-row"><span class="lesson-number">${j+1}</span><div><strong>${t}</strong><small>Лекция · Визуализация · Практика · Квесты</small></div><button class="secondary-btn" data-lesson="${t}">Открыть →</button></div>`).join("")}</div></section>`).join("")}<div class="section-head"><div><span class="tag">Практикум</span><h2>12 лабораторных работ</h2></div></div><div class="lesson-list">${window.IMPULS_LABS_7.map((t,i)=>`<div class="lesson-row"><span class="lesson-number">${i+1}</span><div><strong>${t}</strong><small>Цель · Оборудование · Ход работы · Измерения · Вывод</small></div><span class="empty-note">В разработке</span></div>`).join("")}</div>`;
}
function bindGradeButtons(){document.querySelectorAll("[data-grade]").forEach(b=>b.addEventListener("click",()=>{currentGrade=Number(b.dataset.grade);setPage("program")}))}
function lessonNavigation(topic){
 const allTopics=(window.IMPULS_CURRICULUM_7||[]).flatMap(ch=>ch.items||[]);
 const index=allTopics.indexOf(topic);
 const previous=index>0?allTopics[index-1]:null;
 const next=index>=0&&index<allTopics.length-1?allTopics[index+1]:null;
 return `<nav class="lesson-navigation" aria-label="Навигация по урокам">
  <button class="lesson-nav-button lesson-nav-prev" data-lesson="${previous||""}" ${previous?"":"disabled"} aria-label="Предыдущий урок">
   <span class="lesson-nav-arrow" aria-hidden="true">←</span><span><small>Предыдущий урок</small><strong>${previous||"Начало курса"}</strong></span>
  </button>
  <span class="lesson-nav-count">${index>=0?index+1+" / "+allTopics.length:"Урок"}</span>
  <button class="lesson-nav-button lesson-nav-next" data-lesson="${next||""}" ${next?"":"disabled"} aria-label="Следующий урок">
   <span><small>Следующий урок</small><strong>${next||"Конец курса"}</strong></span><span class="lesson-nav-arrow" aria-hidden="true">→</span>
  </button>
 </nav>`;
}
function lessonPage(topic){
 const lesson=(window.IMPULS_LESSONS_7||{})[topic];
 if(!lesson)return `<button class="text-link" data-go="program">← К программе</button><div class="section-head"><div><span class="tag">7 класс · Материал готовится</span><h1 class="page-title">${topic}</h1><p class="page-intro">Тема включена в структуру курса. Полный авторский материал будет подготовлен после сверки с рабочей программой школы.</p></div></div><div class="result-box">В разработке: краткая лекция, подробное объяснение, визуальная модель, практика и проверка знаний.</div>`;
 return `<button class="text-link" data-go="program">← К программе</button>
 <div class="lesson-hero"><span class="tag">${lesson.chapter||"7 класс · Введение"} · ${lesson.paragraph||"§ 1"}</span><h1 class="page-title">${lesson.title}</h1><p class="page-intro">${lesson.lead}</p></div>
 <section class="lesson-section"><span class="tag">01 · Быстрый старт</span><h2>Главная мысль</h2><p>${lesson.short}</p><div class="lesson-callout"><strong>Запомни:</strong> ${lesson.key}</div></section>
 <section class="lesson-section"><span class="tag">02 · Разбираемся</span><h2>${lesson.title}</h2>${lesson.explanation.map(p=>`<p>${p}</p>`).join("")}<div class="lesson-topic-grid">${lesson.groups.map(g=>`<article class="content-card"><span class="tag">${g.name}</span><h3>${g.title}</h3><p>${g.example}</p></article>`).join("")}</div></section>
 <section class="lesson-section"><span class="tag">03 · Посмотри вокруг</span><h2>Физика рядом с тобой</h2><p>Выбери ситуацию и попробуй назвать физическое явление, которое в ней происходит.</p><div class="lesson-observations">${lesson.observations.map((o,i)=>`<button class="observation-card" data-observation="${i}"><strong>${o.scene}</strong><span>${o.prompt}</span><small class="observation-answer">${o.answer}</small></button>`).join("")}</div></section>
 <section class="lesson-section"><span class="tag">04 · Попробуй сам</span><h2>Мини-исследование</h2><p>${lesson.practice}</p><ol>${lesson.steps.map(x=>`<li>${x}</li>`).join("")}</ol><div class="lesson-callout">Результат исследования: ${lesson.conclusion}</div></section>
 <section class="lesson-section"><span class="tag">05 · Проверь себя</span><h2>Короткая проверка</h2><p>${lesson.question}</p><div class="quiz-options">${lesson.answers.map((x,i)=>`<label><input type="radio" name="intro-quiz" value="${i}"> ${x}</label>`).join("")}</div><button class="primary-btn" id="lesson-quiz-check">Проверить ответ</button><p id="lesson-quiz-result" class="empty-note"></p></section>
 <div class="hero-actions"><button class="primary-btn" id="complete-lesson">Отметить урок пройденным</button><button class="secondary-btn" data-go="program">К списку тем</button></div>${lessonNavigation(topic)}`;
}
function labPage(){return `<h1 class="page-title">Виртуальная лаборатория</h1><p class="page-intro">Меняйте параметры эксперимента и наблюдайте, как меняется движение. Это учебная модель, а не замена реального лабораторного оборудования.</p><div class="lab-catalog" id="lab-catalog"><div class="section-head"><div><h2>Выбери эксперимент</h2><p>Открой лабораторию, настрой параметры и проведи собственное исследование.</p></div></div><div class="lab-card-grid"><button class="lab-card" data-lab-open="lab-newton"><span class="lab-card-icon">⚙️</span><span class="tag">Механика</span><strong>Второй закон Ньютона</strong><small>Сила, масса и ускорение</small><span class="lab-card-link">Открыть эксперимент →</span></button><button class="lab-card" data-lab-open="lab-density"><span class="lab-card-icon">⚖️</span><span class="tag">Вещество</span><strong>Измерение плотности</strong><small>Масса, объём и плотность образца</small><span class="lab-card-link">Открыть эксперимент →</span></button><button class="lab-card" data-lab-open="lab-spring"><span class="lab-card-icon">〰️</span><span class="tag">Силы</span><strong>Закон Гука</strong><small>Сила упругости и удлинение пружины</small><span class="lab-card-link">Открыть эксперимент →</span></button><button class="lab-card" data-lab-open="lab-gravity"><span class="lab-card-icon">🌍</span><span class="tag">Тяготение</span><strong>Сила тяжести</strong><small>Земля, Луна, Марс и Юпитер</small><span class="lab-card-link">Открыть эксперимент →</span></button><button class="lab-card" data-lab-open="lab-friction"><span class="lab-card-icon">🧱</span><span class="tag">Взаимодействие</span><strong>Сила трения</strong><small>Материалы поверхностей и сила прижатия</small><span class="lab-card-link">Открыть эксперимент →</span></button><button class="lab-card" data-lab-open="lab-resultant"><span class="lab-card-icon">↔️</span><span class="tag">Силы</span><strong>Равнодействующая сил</strong><small>Сложение сил и их направления</small><span class="lab-card-link">Открыть эксперимент →</span></button><button class="lab-card" data-lab-open="lab-molecules"><span class="lab-card-icon">🔬</span><span class="tag">Молекулярная физика</span><strong>Загляни внутрь вещества</strong><small>Твёрдое тело, жидкость и газ</small><span class="lab-card-link">Открыть эксперимент →</span></button><button class="lab-card" data-lab-open="lab-hydrostatic"><span class="lab-card-icon">💧</span><span class="tag">Давление · Глава 3</span><strong>Давление жидкости</strong><small>Глубина, плотность и давление</small><span class="lab-card-link">Открыть эксперимент →</span></button></div><div class="lab-coming-soon"><strong>Следующие лаборатории</strong><p>Сообщающиеся сосуды · Закон Паскаля · Гидравлический пресс · Архимедова сила</p><span class="empty-note">Готовятся к разработке</span></div></div><div class="lab-detail" id="lab-detail" hidden><button class="text-link lab-back" data-lab-back>← Ко всем лабораториям</button><div class="lab-detail-head"><span class="tag">Виртуальная лаборатория</span><p>Измени параметры эксперимента и наблюдай физический закон на практике.</p></div><div class="simulator" id="lab-newton"><span class="tag">Механика · Второй закон Ньютона</span><h2 style="font-size:18px">Как сила и масса влияют на ускорение?</h2><div class="simulator-stage"><div class="cart-track"><div class="cart" id="cart"></div></div></div><div class="sim-controls"><div class="control"><label>Равнодействующая сила <b><span id="force-value">6</span> Н</b></label><input id="force" type="range" min="1" max="20" value="6"></div><div class="control"><label>Масса <b><span id="mass-value">2</span> кг</b></label><input id="mass" type="range" min="1" max="10" value="2"></div></div><div class="section-head"><div><h2>Результат эксперимента</h2><p>В идеализированной модели без учёта трения</p></div></div><div class="result-box">Ускорение тележки<strong id="acceleration">3,0 м/с²</strong><span id="experiment-explain">При выбранных параметрах ускорение равно отношению силы к массе.</span></div></div><section class="molecule-lab density-lab" id="lab-density"><span class="tag">Лабораторная работа · 7 класс · § 22–24</span><h2>Измерь массу и найди плотность</h2><p class="page-intro">Измени массу образца и его объём. Сначала представь, что измеряешь их в лаборатории, затем рассчитай плотность.</p><div class="sim-controls"><div class="control"><label>Масса образца <b><span id="density-mass-value">200</span> г</b></label><input id="density-mass" type="range" min="50" max="1000" step="10" value="200"></div><div class="control"><label>Объём образца <b><span id="density-volume-value">100</span> см³</b></label><input id="density-volume" type="range" min="10" max="500" step="5" value="100"></div></div><div class="molecule-stage"><svg viewBox="0 0 720 230" role="img" aria-label="Схема измерения массы и объёма образца"><rect x="35" y="155" width="650" height="5" rx="2" fill="#55728e"/><rect x="105" y="80" width="210" height="72" rx="10" fill="#153c60" stroke="#58d7f3" stroke-width="3"/><rect x="145" y="95" width="130" height="42" rx="5" fill="#0a1b32" stroke="#9bdcf0"/><text x="210" y="122" fill="#eaf8ff" font-size="22" text-anchor="middle" id="density-scale-display">200 г</text><path d="M210 152v15m-75 0h150" stroke="#9ab7d0" stroke-width="4" stroke-linecap="round"/><path d="M470 45h110l-12 112h-86z" fill="rgba(88,215,243,.12)" stroke="#58d7f3" stroke-width="3"/><path d="M475 105h100" stroke="#58d7f3" stroke-width="2" stroke-dasharray="6 5"/><rect x="494" y="72" width="62" height="33" rx="5" fill="#ffc45b" opacity=".9"/><text x="525" y="94" fill="#17263b" font-size="14" text-anchor="middle">тело</text><text x="210" y="30" fill="#b9d8eb" font-size="16" text-anchor="middle">Весы · масса</text><text x="525" y="30" fill="#b9d8eb" font-size="16" text-anchor="middle">Мерный сосуд · объём</text><text x="525" y="190" fill="#9fb7d0" font-size="14" text-anchor="middle" id="density-volume-label">V = 100 см³</text></svg><div class="molecule-legend"><span>⚖️ Масса — измеряем весами</span><span>🧪 Объём — определяем по шкале сосуда</span></div></div><div class="result-box" style="margin-top:16px">Плотность образца<strong id="density-result">2,0 г/см³</strong><span id="density-explain">ρ = 200 г / 100 см³ = 2 г/см³</span></div><div class="molecule-readout"><h3>Сравнение с известными веществами</h3><p id="density-compare">Значение близко к плотности некоторых распространённых твёрдых материалов. Сравнение ориентировочное.</p><div class="molecule-stats"><span>Формула: <b>ρ = m / V</b></span><span>Масса: <b id="density-mass-summary">200 г</b></span><span>Объём: <b id="density-volume-summary">100 см³</b></span></div></div><p class="model-note">Это учебная модель измерения. Она не определяет реальное вещество по одному измерению: плотность может зависеть от температуры, состава и погрешности эксперимента.</p></section><section class="molecule-lab force-lab" id="lab-spring"><span class="tag">Виртуальный эксперимент · 7 класс · § 27</span><h2>Исследуй силу упругости</h2><p class="page-intro">Измени силу и жёсткость пружины. Наблюдай, как меняется её удлинение.</p><div class="sim-controls"><div class="control"><label>Сила <b><span id="spring-force-value">4</span> Н</b></label><input id="spring-force" type="range" min="1" max="10" value="4"></div><div class="control"><label>Жёсткость <b><span id="spring-k-value">200</span> Н/м</b></label><input id="spring-k" type="range" min="100" max="500" step="50" value="200"></div></div><div class="molecule-stage" style="padding:24px"><div style="display:flex;align-items:center;gap:10px"><div style="width:28px;height:72px;border-left:7px solid #8da9c3"></div><div id="spring-visual" style="height:24px;min-width:50px;width:180px;border:3px solid #58d7f3;border-radius:14px;background:repeating-linear-gradient(135deg,transparent 0 7px,#58d7f3 8px 11px,transparent 12px 18px);transition:width .2s"></div><div style="font-size:28px">➜</div></div><p id="spring-extension-label">Удлинение: 0,02 м (2 см)</p></div><div class="result-box">Удлинение пружины<strong id="spring-extension">0,02 м</strong><span id="spring-equation">x = F / k = 4 / 200 = 0,02 м</span></div><p class="model-note">Модель использует закон Гука для идеальной пружины в пределах упругой деформации. Это не реальный измерительный прибор.</p></section><section class="molecule-lab" id="lab-gravity"><span class="tag">Исследование · 7 класс · § 26 и § 29</span><h2>Сравни силу тяжести на небесных телах</h2><div class="control"><label>Масса тела <b><span id="gravity-mass-value">10</span> кг</b></label><input id="gravity-mass" type="range" min="1" max="100" value="10"></div><div class="control"><label>Небесное тело</label><select id="gravity-world"><option value="9.8">Земля · 9,8 Н/кг</option><option value="1.6">Луна · 1,6 Н/кг</option><option value="3.7">Марс · 3,7 Н/кг</option><option value="24.8">Юпитер · 24,8 Н/кг</option></select></div><div class="result-box">Сила тяжести<strong id="gravity-result">98 Н</strong><span id="gravity-explain">Fтяж = m · g = 10 · 9,8 = 98 Н</span></div><p class="model-note">Масса тела остаётся прежней. Меняется сила тяжести из-за различия ускорения свободного падения.</section><section class="molecule-lab friction-lab" id="lab-friction"><span class="tag">Виртуальный эксперимент · 7 класс · § 32</span><h2>Исследуй силу трения</h2><p class="page-intro">Меняй силу прижатия и материал поверхности. Сравни, как изменяется сила трения скольжения в упрощённой модели.</p><div class="sim-controls"><div class="control"><label>Прижимающая сила N <b><span id="friction-normal-value">20</span> Н</b></label><input id="friction-normal" type="range" min="5" max="100" value="20"></div><div class="control"><label>Поверхности</label><select id="friction-surface"><option value="0.15">Лёд по льду · μ = 0,15</option><option value="0.3" selected>Дерево по дереву · μ = 0,30</option><option value="0.6">Резина по сухому бетону · μ = 0,60</option></select></div></div><div class="molecule-stage" style="padding:24px"><div style="height:95px;position:relative;border-bottom:8px solid #7892aa"><div id="friction-block" style="position:absolute;left:30%;bottom:8px;width:88px;height:58px;border-radius:9px 9px 3px 3px;background:linear-gradient(135deg,#e9b86a,#986333);border:2px solid #ffdb9b;transition:transform .2s"></div><div style="position:absolute;left:calc(30% + 96px);bottom:23px;color:#58d7f3;font-size:24px">← Fтр</div></div><p id="friction-readout">Сила трения: 6 Н</p></div><div class="result-box">Сила трения скольжения<strong id="friction-result">6 Н</strong><span id="friction-equation">Fтр = μ · N = 0,30 · 20 = 6 Н</span></div><p class="model-note">Коэффициенты приведены как учебные ориентиры. Реальное трение зависит от конкретных материалов, состояния поверхностей и условий эксперимента.</p></section><section class="molecule-lab resultant-lab" id="lab-resultant"><span class="tag">Виртуальный эксперимент · 7 класс · § 31</span><h2>Сложи две силы</h2><p class="page-intro">Измени значения сил и выбери их направления. Найди равнодействующую.</p><div class="sim-controls"><div class="control"><label>Сила F₁ <b><span id="resultant-f1-value">8</span> Н</b></label><input id="resultant-f1" type="range" min="0" max="20" value="8"></div><div class="control"><label>Сила F₂ <b><span id="resultant-f2-value">3</span> Н</b></label><input id="resultant-f2" type="range" min="0" max="20" value="3"></div><div class="control"><label>Направление второй силы</label><select id="resultant-direction"><option value="same">В ту же сторону, что F₁</option><option value="opposite" selected>В противоположную сторону</option></select></div></div><div class="molecule-stage" style="padding:22px;text-align:center"><div style="font-size:34px">▰</div><div style="display:flex;justify-content:center;gap:20px;flex-wrap:wrap"><span id="resultant-arrow1">F₁ → 8 Н</span><span id="resultant-arrow2">F₂ ← 3 Н</span></div><p id="resultant-direction-result">Равнодействующая направлена вправо</p></div><div class="result-box">Равнодействующая<strong id="resultant-result">5 Н →</strong><span id="resultant-equation">R = |F₁ − F₂| = |8 − 3| = 5 Н</span></div><p class="model-note">Рассматриваются только две силы, действующие вдоль одной прямой. Направление результата определяется большей силой.</p></section><section class="molecule-lab" id="lab-molecules"><span class="tag">Исследование · 7 класс · § 7–13</span><h2>Загляни внутрь вещества</h2><p class="page-intro">Переключай состояния вещества, меняй температуру и наблюдай движение частиц.</p><div class="phase-tabs"><button class="phase-btn active" data-phase="solid">Твёрдое</button><button class="phase-btn" data-phase="liquid">Жидкость</button><button class="phase-btn" data-phase="gas">Газ</button></div><div class="molecule-stage"><canvas id="molecule-canvas" width="760" height="340"></canvas><div class="molecule-legend"><span>🔵 Частицы вещества</span><span>🟡 Частицы второго вещества</span></div></div><div class="molecule-controls"><label>Температура модели: <b><span id="molecule-temp-value">20</span> °C</b><input id="molecule-temp" type="range" min="0" max="100" value="20"></label><button class="secondary-btn" id="molecule-mix">Добавить второе вещество</button></div><div class="molecule-readout"><h3 id="molecule-phase-title">Твёрдое состояние</h3><p id="molecule-description">Частицы расположены близко и упорядоченно. Они колеблются около устойчивых положений.</p><div class="molecule-stats"><span>Подвижность: <b id="molecule-motion">Низкая</b></span><span>Промежутки: <b id="molecule-distance">Малые</b></span><span>Форма: <b id="molecule-shape">Сохраняется</b></span></div></div><p class="model-note">Учебная модель условна: размеры и расстояния не соответствуют реальному масштабу. Ползунок меняет интенсивность движения частиц в модели, а не рассчитывает состояние конкретного вещества.</p></section><section class="molecule-lab hydrostatic-lab" id="lab-hydrostatic"><span class="tag">Виртуальный эксперимент · 7 класс · Глава 3</span><h2>Исследуй давление жидкости</h2><p class="page-intro">Измени глубину и выбери жидкость. Посмотри, как меняется гидростатическое давление на одном и том же уровне.</p><div class="sim-controls"><div class="control"><label>Глубина погружения <b><span id="hydro-depth-value">1,0</span> м</b></label><input id="hydro-depth" type="range" min="0" max="5" step="0.1" value="1"></div><div class="control"><label>Жидкость</label><select id="hydro-liquid"><option value="1000" selected>Вода · 1000 кг/м³</option><option value="900">Масло (условно) · 900 кг/м³</option><option value="1030">Морская вода · 1030 кг/м³</option><option value="800">Лёгкая жидкость · 800 кг/м³</option></select></div><div class="control"><label>Ускорение свободного падения</label><select id="hydro-gravity"><option value="9.8" selected>Земля · 9,8 м/с²</option><option value="1.6">Луна · 1,6 м/с²</option><option value="3.7">Марс · 3,7 м/с²</option></select></div></div><div class="molecule-stage hydro-stage"><svg viewBox="0 0 360 230" role="img" aria-label="Сосуд с жидкостью и датчик давления на выбранной глубине"><path d="M70 24V198Q70 207 80 207H220Q230 207 230 198V24" fill="none" stroke="#9bdcf0" stroke-width="5" stroke-linecap="round"/><rect x="74" y="62" width="152" height="142" fill="#28a9dc" opacity=".36"/><path d="M75 62H225" stroke="#7ce7ff" stroke-width="3"/><path id="hydro-probe-line" d="M75 90H245" stroke="#ffcf70" stroke-width="2" stroke-dasharray="5 4"/><circle id="hydro-probe" cx="245" cy="90" r="8" fill="#ffcf70" stroke="#fff0c4" stroke-width="2"/><path d="M245 90l23 -18" stroke="#ffcf70" stroke-width="2"/><text x="272" y="68" fill="#ffcf70" font-size="11">Датчик</text><path d="M45 28V194m-5 -8 5 8 5 -8" stroke="#9bdcf0" stroke-width="2" fill="none"/><text x="18" y="115" fill="#b9d8eb" font-size="11" transform="rotate(-90 18 115)" text-anchor="middle">Глубина</text><text x="150" y="222" fill="#b9d8eb" font-size="12" text-anchor="middle">Схема сосуда · не в масштабе</text></svg><div class="molecule-legend"><span>🔵 Жидкость</span><span>🟡 Датчик давления</span></div></div><div class="result-box">Гидростатическое давление<strong id="hydro-pressure">9,8 кПа</strong><span id="hydro-equation">p = ρgh = 1000 · 9,8 · 1 = 9800 Па</span></div><div class="molecule-readout"><h3>Что показывает опыт?</h3><p id="hydro-explain">Чем глубже точка в жидкости, тем больше давление. При одинаковой глубине давление зависит также от плотности жидкости и значения g.</p><div class="molecule-stats"><span>Плотность: <b id="hydro-density">1000 кг/м³</b></span><span>Глубина: <b id="hydro-depth-summary">1,0 м</b></span><span>Давление: <b id="hydro-pressure-summary">9,8 кПа</b></span></div></div><p class="model-note">Рассчитывается избыточное гидростатическое давление p = ρgh относительно поверхности жидкости. Атмосферное давление не включено. Жидкость считается однородной и неподвижной.</p></section><button class="secondary-btn lab-back-bottom" data-lab-back>← Ко всем лабораториям</button></div>`}
function bindHydrostaticLab(){const depth=document.getElementById("hydro-depth"),liquid=document.getElementById("hydro-liquid"),gravity=document.getElementById("hydro-gravity");if(!depth||!liquid||!gravity)return;const fmt=(v,d=1)=>v.toFixed(d).replace(".",",");const update=()=>{const h=Number(depth.value),rho=Number(liquid.value),g=Number(gravity.value),p=rho*g*h,pk=p/1000;document.getElementById("hydro-depth-value").textContent=fmt(h);document.getElementById("hydro-density").textContent=rho+" кг/м³";document.getElementById("hydro-depth-summary").textContent=fmt(h)+" м";document.getElementById("hydro-pressure").textContent=fmt(pk)+" кПа";document.getElementById("hydro-pressure-summary").textContent=fmt(pk)+" кПа";document.getElementById("hydro-equation").textContent="p = ρgh = "+rho+" · "+fmt(g)+" · "+fmt(h)+" = "+fmt(p,0)+" Па";const y=62+Math.max(0,Math.min(1,h/5))*112;document.getElementById("hydro-probe-line").setAttribute("d","M75 "+y+"H245");document.getElementById("hydro-probe").setAttribute("cy",y);document.getElementById("hydro-explain").textContent=h===0?"На поверхности жидкости избыточное гидростатическое давление равно нулю.":"На глубине "+fmt(h)+" м давление равно "+fmt(pk)+" кПа. При увеличении глубины давление возрастает прямо пропорционально h.";};depth.addEventListener("input",update);liquid.addEventListener("change",update);gravity.addEventListener("change",update);update();}
function bindFrictionAndResultant(){const n=document.getElementById("friction-normal"),s=document.getElementById("friction-surface");if(n&&s){const fmt=x=>x.toFixed(2).replace(".",",");const calc=()=>{const N=+n.value,mu=+s.value,F=N*mu;document.getElementById("friction-normal-value").textContent=N;document.getElementById("friction-result").textContent=fmt(F)+" Н";document.getElementById("friction-readout").textContent="Сила трения скольжения: "+fmt(F)+" Н";document.getElementById("friction-equation").textContent="Fтр = μ · N = "+fmt(mu)+" · "+N+" = "+fmt(F)+" Н";document.getElementById("friction-block").style.transform="translateX("+Math.min(45,F*1.2)+"px)"};n.addEventListener("input",calc);s.addEventListener("change",calc);calc()}const f1=document.getElementById("resultant-f1"),f2=document.getElementById("resultant-f2"),dir=document.getElementById("resultant-direction");if(f1&&f2&&dir){const calc=()=>{const a=+f1.value,b=+f2.value,same=dir.value==="same",signed=same?a+b:a-b,R=Math.abs(signed),arrow=signed>0?"→":signed<0?"←":"0";document.getElementById("resultant-f1-value").textContent=a;document.getElementById("resultant-f2-value").textContent=b;document.getElementById("resultant-arrow1").textContent="F₁ → "+a+" Н";document.getElementById("resultant-arrow2").textContent="F₂ "+(same?"→ ":"← ")+b+" Н";document.getElementById("resultant-result").textContent=R+" Н "+arrow;document.getElementById("resultant-direction-result").textContent=R===0?"Равнодействующая равна нулю": "Равнодействующая направлена "+(signed>0?"вправо":"влево");document.getElementById("resultant-equation").textContent=same?"R = F₁ + F₂ = "+a+" + "+b+" = "+R+" Н":"R = |F₁ − F₂| = |"+a+" − "+b+"| = "+R+" Н"};[f1,f2].forEach(el=>el.addEventListener("input",calc));dir.addEventListener("change",calc);calc()}}function bindForceLab(){const f=document.getElementById("spring-force"),k=document.getElementById("spring-k"),gm=document.getElementById("gravity-mass"),gw=document.getElementById("gravity-world");if(f&&k){const fmt=n=>n.toFixed(2).replace(".",",");const calc=()=>{const force=+f.value,stiff=+k.value,x=force/stiff;document.getElementById("spring-force-value").textContent=force;document.getElementById("spring-k-value").textContent=stiff;document.getElementById("spring-extension").textContent=fmt(x)+" м";document.getElementById("spring-extension-label").textContent="Удлинение: "+fmt(x)+" м ("+fmt(x*100)+" см)";document.getElementById("spring-equation").textContent="x = F / k = "+force+" / "+stiff+" = "+fmt(x)+" м";document.getElementById("spring-visual").style.width=(Math.min(360,90+x*2200))+"px"};f.addEventListener("input",calc);k.addEventListener("input",calc);calc()}if(gm&&gw){const calc=()=>{const mass=+gm.value,g=+gw.value,F=mass*g;document.getElementById("gravity-mass-value").textContent=mass;document.getElementById("gravity-result").textContent=F.toFixed(1).replace(".",",")+" Н";document.getElementById("gravity-explain").textContent="Fтяж = m · g = "+mass+" · "+g+" = "+F.toFixed(1).replace(".",",")+" Н"};gm.addEventListener("input",calc);gw.addEventListener("change",calc);calc()}}function bindDensityLab(){const m=document.getElementById("density-mass"),v=document.getElementById("density-volume");if(!m||!v)return;const fmt=n=>Number(n).toFixed(1).replace(".",",");function calc(){const mass=Number(m.value),volume=Number(v.value),rho=mass/volume;document.getElementById("density-mass-value").textContent=mass;document.getElementById("density-volume-value").textContent=volume;document.getElementById("density-scale-display").textContent=mass+" г";document.getElementById("density-volume-label").textContent="V = "+volume+" см³";document.getElementById("density-result").textContent=fmt(rho)+" г/см³";document.getElementById("density-explain").textContent="ρ = "+mass+" г / "+volume+" см³ = "+fmt(rho)+" г/см³";document.getElementById("density-mass-summary").textContent=mass+" г";document.getElementById("density-volume-summary").textContent=volume+" см³";let label;if(Math.abs(rho-1)<.12)label="Полученная плотность близка к плотности воды (около 1 г/см³).";else if(Math.abs(rho-2.7)<.18)label="Полученная плотность близка к плотности алюминия (около 2,7 г/см³).";else if(Math.abs(rho-7.8)<.35)label="Полученная плотность близка к плотности железа (около 7,8 г/см³).";else if(rho<1)label="Плотность меньше плотности воды. Некоторые материалы с такой плотностью могут плавать в воде.";else label="Сравни результат с таблицей плотностей веществ. Это значение само по себе не позволяет точно определить материал.";document.getElementById("density-compare").textContent=label;}m.addEventListener("input",calc);v.addEventListener("input",calc);calc();}function updateSimulation(){const f=document.getElementById("force"),m=document.getElementById("mass");if(!f||!m)return;const calc=()=>{let force=+f.value,mass=+m.value,a=force/mass;document.getElementById("force-value").textContent=force;document.getElementById("mass-value").textContent=mass;document.getElementById("acceleration").textContent=a.toFixed(1).replace(".",",")+" м/с²";document.getElementById("cart").style.left=(20+Math.min(60,a*5))+"%";document.getElementById("experiment-explain").textContent=`При равнодействующей силе ${force} Н и массе ${mass} кг ускорение составляет ${a.toFixed(1).replace(".",",")} м/с².`};f.addEventListener("input",calc);m.addEventListener("input",calc);calc()}
function questsPage(){return `<div class="quest-hero"><span class="eyebrow">ИССЛЕДОВАТЕЛЬСКАЯ СРЕДА ИМПУЛЬС</span><h1>Заметь. Почувствуй. Исследуй.</h1><p>Начни с наблюдения, задай вопрос, исследуй невидимое и самостоятельно открой закон природы.</p></div><div class="quest-grid"><article class="quest-card"><span class="tag">Квест 001 · 7 класс · § 10</span><h2>Куда исчезает запах?</h2><p>Как аромат духов оказывается в другом конце комнаты? Загляни в невидимый мир молекул.</p><button class="primary-btn" data-start-diffusion>Начать исследование →</button></article><article class="quest-card"><span class="tag">Квест 002 · 7 класс · § 9</span><h2>Почему пылинки танцуют?</h2><p>Невидимые молекулы воды толкают крошечную частицу со всех сторон. Посмотри, как это происходит.</p><button class="primary-btn" data-start-brownian>Начать исследование →</button></article><article class="quest-card"><span class="tag">Квест 003 · 7 класс · § 19</span><h2>Почему пассажира бросает вперёд?</h2><p>Автобус тормозит, а тело стремится сохранить прежнее движение. Исследуй инерцию.</p><button class="primary-btn" data-start-inertia>Начать исследование →</button></article></div>`}
function brownianPage(){return `<button class="text-link" data-go="quests">← К квестам</button><div class="quest-stage"><span class="tag">Квест 002 · Броуновское движение · § 9</span><h1>Почему пылинки танцуют?</h1><h2>1. Заметь</h2><p>Под микроскопом маленькая частица, взвешенная в воде, беспорядочно меняет направление движения. Вода кажется неподвижной. Что может толкать частицу?</p><div class="quiz-options"><label><input type="radio" name="brownian-hyp" value="molecules"> Удары быстро движущихся молекул воды</label><label><input type="radio" name="brownian-hyp" value="gravity"> Только сила тяжести</label><label><input type="radio" name="brownian-hyp" value="still"> Частицы воды неподвижны</label></div><button class="primary-btn" id="brownian-check">Проверить гипотезу</button><p id="brownian-hypout" class="empty-note"></p><h2>2. Посмотри внутрь невидимого</h2><p>Голубые точки — условные молекулы воды, крупная золотая частица — наблюдаемая взвешенная частица. Неравномерные удары с разных сторон меняют её движение.</p><canvas id="brownian-canvas" width="720" height="300" aria-label="Модель броуновского движения"></canvas><label>Температура модели: <b><span id="brownian-temp-value">20</span> °C</b></label><input id="brownian-temp" type="range" min="0" max="100" value="20"><button class="secondary-btn" id="brownian-reset">Сбросить траекторию</button><h2>3. Пойми</h2><p><b>Броуновское движение</b> — непрерывное хаотическое движение мелких частиц, взвешенных в жидкости или газе, вызванное ударами молекул среды. При повышении температуры тепловое движение молекул обычно становится интенсивнее.</p><h2>4. Проверь себя</h2><p>Почему взвешенная частица меняет направление?</p><div class="quiz-options"><label><input type="radio" name="brownian-final" value="yes"> Молекулы среды ударяют по ней не одинаково со всех сторон</label><label><input type="radio" name="brownian-final" value="no"> Частица сама выбирает направление</label></div><button class="primary-btn" id="brownian-finish">Завершить квест</button><p id="brownian-result" class="empty-note"></p></div>`;}
function inertiaPage(){return `<button class="text-link" data-go="quests">← К квестам</button><div class="quest-stage"><span class="tag">Квест 003 · Инерция · § 19</span><h1>Почему пассажира бросает вперёд?</h1><h2>1. Заметь</h2><p>Автобус движется, затем резко тормозит. Пассажир, который не держится за поручень, наклоняется вперёд. Как ты думаешь, почему?</p><div class="quiz-options"><label><input type="radio" name="inertia-hyp" value="keep"> Тело пассажира стремится сохранить прежнюю скорость</label><label><input type="radio" name="inertia-hyp" value="push"> Автобус притягивает пассажира вперёд</label><label><input type="radio" name="inertia-hyp" value="gravity"> Меняется сила тяжести</label></div><button class="primary-btn" id="inertia-check">Проверить гипотезу</button><p id="inertia-hypout" class="empty-note"></p><h2>2. Посмотри на модель</h2><p>Нажми «Запустить». Сначала автобус движется, затем тормозит. Золотая точка условно показывает положение пассажира относительно дороги, а голубая рамка — автобус.</p><canvas id="inertia-canvas" width="720" height="260" aria-label="Модель движения автобуса при торможении"></canvas><div class="hero-actions"><button class="primary-btn" id="inertia-run">Запустить движение</button><button class="secondary-btn" id="inertia-reset">Сбросить</button></div><p id="inertia-state" class="empty-note">Наблюдай, как меняется положение пассажира относительно автобуса.</p><h2>3. Пойми</h2><p><b>Инерция</b> — явление сохранения скорости тела, когда действие других тел отсутствует или их действия скомпенсированы. При торможении автобуса он замедляется, а пассажир стремится сохранить прежнюю скорость относительно дороги. Поэтому относительно автобуса пассажир смещается вперёд.</p><p>Инерция — не отдельная сила. Это явление, которое помогает объяснить сохранение состояния движения.</p><h2>4. Проверь себя</h2><p>Что происходит с пассажиром, когда автобус начинает движение вперёд?</p><div class="quiz-options"><label><input type="radio" name="inertia-final" value="back"> Пассажир может отклониться назад относительно автобуса</label><label><input type="radio" name="inertia-final" value="front"> Пассажир всегда наклоняется вперёд</label></div><button class="primary-btn" id="inertia-finish">Завершить квест</button><p id="inertia-result" class="empty-note"></p></div>`;}
function bindInertia(){const c=document.getElementById("inertia-canvas");if(!c)return;const ctx=c.getContext("2d"),W=720,H=260;let busX=70,passengerX=190,phase=0,raf=0,running=false;function draw(){ctx.clearRect(0,0,W,H);ctx.fillStyle="#07182d";ctx.fillRect(0,0,W,H);ctx.strokeStyle="rgba(255,255,255,.22)";ctx.setLineDash([12,12]);ctx.beginPath();ctx.moveTo(0,220);ctx.lineTo(W,220);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle="#163b5b";ctx.strokeStyle="#58d7f3";ctx.lineWidth=3;ctx.beginPath();ctx.roundRect(busX,90,300,125,18);ctx.fill();ctx.stroke();ctx.fillStyle="#8be8ff";ctx.fillRect(busX+20,105,110,48);ctx.fillRect(busX+150,105,110,48);ctx.fillStyle="#ffc45b";ctx.beginPath();ctx.arc(passengerX,154,12,0,Math.PI*2);ctx.fill();ctx.strokeStyle="#ffc45b";ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(passengerX,166);ctx.lineTo(passengerX+12,198);ctx.stroke();ctx.fillStyle="#eaf4ff";ctx.font="14px sans-serif";ctx.fillText("Автобус",busX+115,82);ctx.fillText("Пассажир",passengerX-35,132);ctx.fillStyle="#58d7f3";ctx.fillText("Направление движения →",470,35);if(running){if(phase<75){busX+=2.1;passengerX+=2.1;phase++;}else if(phase<120){busX+=Math.max(.08,2.1*(1-(phase-75)/45));passengerX+=1.65;phase++;}else{running=false;document.getElementById("inertia-state").textContent="Автобус остановился, а пассажир сместился вперёд относительно салона. Это проявление инерции.";}}raf=requestAnimationFrame(draw);}function reset(){running=false;phase=0;busX=70;passengerX=190;document.getElementById("inertia-state").textContent="Модель готова. Запусти движение и наблюдай за пассажиром.";}document.getElementById("inertia-run").addEventListener("click",()=>{if(phase>=120)reset();running=true;document.getElementById("inertia-state").textContent="Автобус движется, затем начинает тормозить…";});document.getElementById("inertia-reset").addEventListener("click",reset);document.getElementById("inertia-check").addEventListener("click",()=>{const v=document.querySelector('input[name="inertia-hyp"]:checked');document.getElementById("inertia-hypout").textContent=!v?"Сначала выбери гипотезу.":v.value==="keep"?"Верно. Пассажир стремится сохранить прежнюю скорость относительно дороги.":"Подумай, что происходит с телом, когда автобус замедляется, а тело продолжает прежнее движение."});document.getElementById("inertia-finish").addEventListener("click",()=>{const v=document.querySelector('input[name="inertia-final"]:checked');document.getElementById("inertia-result").textContent=!v?"Выбери ответ.":v.value==="back"?"Верно! При начале движения автобуса пассажир стремится сохранить покой и относительно салона отклоняется назад.":"Попробуй ещё раз: автобус начинает двигаться, а тело пассажира стремится сохранить покой."});reset();draw();}function diffusionPage(){return `<button class="text-link" data-go="quests">← К квестам</button><div class="quest-stage"><span class="tag">Квест 001 · Диффузия</span><h1>Куда исчезает запах?</h1><h2>1. Заметь</h2><p>В одном конце комнаты открыли флакон духов. Через некоторое время запах почувствовали у противоположной стены. Как вещество туда попало?</p><div class="quiz-options"><label><input type="radio" name="hyp" value="air"> Только поток воздуха</label><label><input type="radio" name="hyp" value="diff"> Только диффузия</label><label><input type="radio" name="hyp" value="both"> Диффузия и движение воздуха</label></div><button class="primary-btn" id="hypcheck">Проверить гипотезу</button><p id="hypout" class="empty-note"></p><h2>2. Посмотри внутрь невидимого</h2><p>Жёлтые точки — условные молекулы ароматического вещества, голубые — частицы воздуха. Схема не передаёт реальный масштаб.</p><canvas id="diffcanvas" width="720" height="260"></canvas><label>Температура: <b id="tval">20 °C</b></label><input id="tctrl" type="range" min="5" max="50" step="5" value="20"><label>Поток воздуха</label><select id="airctrl"><option value="0">Нет направленного потока</option><option value="1">Поток вправо</option></select><button class="secondary-btn" id="resetdiff">Сбросить модель</button><h2>3. Пойми</h2><p><b>Диффузия</b> — взаимное проникновение частиц одного вещества между частицами другого вследствие их непрерывного хаотического движения. В комнате распространение запаха обычно связано и с диффузией, и с переносом воздуха.</p><p>Почему повышение температуры обычно ускоряет диффузию?</p><div class="quiz-options"><label><input type="radio" name="finalq" value="yes"> Средняя кинетическая энергия частиц возрастает</label><label><input type="radio" name="finalq" value="no"> Молекулы становятся крупнее</label></div><button class="primary-btn" id="finishdiff">Завершить квест</button><p id="diffresult" class="empty-note"></p></div>`}
function bindQuestButtons(){document.querySelector("[data-start-diffusion]")?.addEventListener("click",()=>{pageContent.innerHTML=diffusionPage();breadcrumbs.textContent="Квест · Диффузия";bindDiffusion();window.scrollTo(0,0)})}
function bindBrownian(){const c=document.getElementById("brownian-canvas");if(!c)return;const ctx=c.getContext("2d"),temp=document.getElementById("brownian-temp");const W=720,H=300;let molecules=[],target={x:360,y:150,trail:[]},frame=0,raf=0;function reset(){molecules=Array.from({length:115},()=>({x:12+Math.random()*(W-24),y:12+Math.random()*(H-24),vx:(Math.random()-.5)*2,vy:(Math.random()-.5)*2}));target={x:360,y:150,vx:0,vy:0,trail:[]};}function draw(){if(!c.isConnected){cancelAnimationFrame(raf);return;}ctx.fillStyle="#07182d";ctx.fillRect(0,0,W,H);const heat=.35+Number(temp.value)/45;ctx.strokeStyle="rgba(255,196,91,.35)";ctx.lineWidth=2;ctx.beginPath();target.trail.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke();molecules.forEach(m=>{m.x+=m.vx*heat;m.y+=m.vy*heat;if(m.x<6||m.x>W-6)m.vx*=-1;if(m.y<6||m.y>H-6)m.vy*=-1;const dx=m.x-target.x,dy=m.y-target.y,d=Math.hypot(dx,dy);if(d<18){target.vx+=(dx/(d||1))*.12*(Math.random()+.2);target.vy+=(dy/(d||1))*.12*(Math.random()+.2);}ctx.beginPath();ctx.arc(m.x,m.y,3,0,7);ctx.fillStyle="#58d7f3";ctx.fill();});target.vx*=.985;target.vy*=.985;target.x+=target.vx*heat;target.y+=target.vy*heat;if(target.x<18||target.x>W-18)target.vx*=-1;if(target.y<18||target.y>H-18)target.vy*=-1;target.trail.push({x:target.x,y:target.y});if(target.trail.length>180)target.trail.shift();ctx.beginPath();ctx.arc(target.x,target.y,10,0,7);ctx.fillStyle="#ffc45b";ctx.shadowBlur=15;ctx.shadowColor="#ffc45b";ctx.fill();ctx.shadowBlur=0;raf=requestAnimationFrame(draw);}document.getElementById("brownian-temp").addEventListener("input",()=>document.getElementById("brownian-temp-value").textContent=temp.value);document.getElementById("brownian-reset").addEventListener("click",reset);document.getElementById("brownian-check").addEventListener("click",()=>{const v=document.querySelector('input[name="brownian-hyp"]:checked');document.getElementById("brownian-hypout").textContent=!v?"Сначала выбери гипотезу.":v.value==="molecules"?"Верно! Молекулы воды движутся хаотически и ударяют по частице с разных сторон.":"Подумай: если вода кажется неподвижной, могут ли её молекулы всё равно двигаться?"});document.getElementById("brownian-finish").addEventListener("click",()=>{const v=document.querySelector('input[name="brownian-final"]:checked');document.getElementById("brownian-result").textContent=!v?"Выбери ответ.":v.value==="yes"?"Верно! Ты завершил исследование броуновского движения.":"Попробуй ещё раз и обрати внимание на удары молекул."});reset();draw();}function bindDiffusion(){const c=document.getElementById("diffcanvas"),x=c.getContext("2d"),t=document.getElementById("tctrl"),air=document.getElementById("airctrl");let ps=[];function reset(){ps=Array.from({length:130},(_,i)=>({x:i<16?25+Math.random()*110:140+Math.random()*560,y:8+Math.random()*244,vx:(Math.random()-.5)*1.5,vy:(Math.random()-.5)*1.5,k:i<16}))}function draw(){x.fillStyle="#07182d";x.fillRect(0,0,720,260);let s=.45+Number(t.value)/30,f=Number(air.value);ps.forEach(p=>{p.x+=p.vx*s+f*.8;p.y+=p.vy*s;if(p.x<4||p.x>716)p.vx*=-1;if(p.y<4||p.y>256)p.vy*=-1;x.beginPath();x.arc(p.x,p.y,p.k?5:3,0,7);x.fillStyle=p.k?"#ffc45b":"#55d8f2";x.fill()});requestAnimationFrame(draw)}reset();draw();t.oninput=()=>document.getElementById("tval").textContent=t.value+" °C";document.getElementById("resetdiff").onclick=reset;document.getElementById("hypcheck").onclick=()=>{let v=document.querySelector('input[name="hyp"]:checked');document.getElementById("hypout").textContent=!v?"Выбери гипотезу.":v.value==="both"?"Верно: в комнате действуют оба процесса.":"Это часть объяснения. Подумай, могут ли процессы действовать одновременно."};document.getElementById("finishdiff").onclick=()=>{let v=document.querySelector('input[name="finalq"]:checked');document.getElementById("diffresult").textContent=!v?"Выбери ответ.":v.value==="yes"?"Верно! Первый квест завершён.":"Подумай о связи температуры и движения частиц."}}
const lifeStories=[
['light','☀','Солнечный луч в классе','Свет','Рассеяние света','Пылинки не светятся сами. Они рассеивают падающий свет в разные стороны, и часть этого света попадает в наши глаза. Так становятся заметны частицы в солнечном луче, капли тумана в свете фар и пыль в помещении.','Посмотри на солнечный луч сбоку, не глядя прямо на Солнце. Заметь, когда частицы становятся заметнее.','Мы видим частицы в луче благодаря рассеянию света.'],
['cooling','☕','Почему остывает чай','Теплота','Теплопередача','Энергия передаётся от более тёплого чая к более холодной чашке и воздуху. Происходят теплопроводность, конвекция и тепловое излучение. По мере охлаждения разность температур обычно уменьшается, поэтому чай остывает медленнее.','Сравни, как остывает одинаковое количество тёплой воды в широкой и узкой чашках. Не используй кипяток.','Тепло самопроизвольно передаётся от более тёплого тела к более холодному.'],
['window','❄','Почему запотевает окно','Теплота','Конденсация водяного пара','В воздухе содержится водяной пар. При соприкосновении с холодным стеклом воздух охлаждается, и часть пара может превратиться в мельчайшие капли. Этот переход газа в жидкость называется конденсацией.','Поставь закрытую холодную бутылку на салфетку и понаблюдай, где появятся капли. Не открывай бутылку до окончания наблюдения.','Капли на холодной поверхности часто образуются из водяного пара воздуха.'],
['bus','🚌','Почему пассажира бросает вперёд при торможении','Движение','Инерция','Когда автобус замедляется, тело пассажира стремится сохранять прежнюю скорость. Опора и поручни постепенно изменяют его движение. Это проявление инерции — свойства тела сохранять состояние покоя или равномерного прямолинейного движения.','Во время безопасной поездки обрати внимание, как пассажиры реагируют на плавный разгон и торможение. Не проводи опыт самостоятельно за рулём.','Инерция объясняет стремление тела сохранять прежнюю скорость.'],
['wind','🌬','Откуда берётся ветер','Атмосфера','Движение воздуха','Земная поверхность нагревается неравномерно. Это влияет на температуру, плотность и давление воздуха. Возникают воздушные потоки; на ветер также влияют вращение Земли, рельеф и трение.','Поднеси лёгкую полоску бумаги рядом с открытым окном, не высовываясь наружу, и понаблюдай за движением воздуха.','Ветер — направленное движение воздушных масс.'],
['pressure','👟','Почему лыжи не проваливаются в снег','Давление','Давление твёрдого тела','Давление равно отношению силы, действующей перпендикулярно поверхности, к площади этой поверхности: p = F/S. При той же силе увеличение площади опоры уменьшает давление. Поэтому лыжи и снегоступы помогают меньше проваливаться в рыхлый снег.','Осторожно надави ладонью на мягкую подушку, затем кончиком одного пальца. Сравни глубину вдавливания, не прикладывая чрезмерной силы.','При одной и той же силе большая площадь опоры создаёт меньшее давление.'],
['sound','🎸','Почему звучит гитарная струна','Колебания и звук','Механические колебания и звуковая волна','Колеблющаяся струна воздействует на воздух, создавая чередование областей повышенного и пониженного давления. Эти возмущения распространяются как звуковая волна. Частота связана с высотой тона, а амплитуда — с громкостью.','Если рядом есть музыкальный инструмент, попроси разрешения слегка коснуться струны после тихого щипка и почувствуй вибрацию.','Звук возникает при колебаниях источника и распространяется в упругой среде.'],
['friction','🚲','Как велосипед тормозит','Силы','Трение и превращение энергии','Тормозные колодки прижимаются к ободу или диску. Возникает сила трения, препятствующая движению. Механическая энергия движения уменьшается, часть её превращается во внутреннюю энергию деталей и окружающей среды.','На неподвижном велосипеде рассмотри тормозной механизм, не касаясь движущихся или горячих деталей.','Трение помогает тормозить, но сопровождается нагреванием и износом.'],
['medicine','🩺','Как тонометр измеряет давление','Физика и медицина','Давление и измерения','Манжета временно сдавливает плечо. При выпускании воздуха прибор регистрирует колебания давления, связанные с пульсацией артерии. Автоматический тонометр обрабатывает сигнал и оценивает систолическое и диастолическое давление. Это давление крови, а не атмосферное.','Найди на тонометре манжету, трубку и экран. Определи назначение каждой части. Не делай выводов о здоровье по учебному примеру.','Тонометр использует физические принципы измерения давления; результат зависит от правильной процедуры.'],
['syringe','💉','Как работает шприц','Физика и медицина','Разность давлений','При оттягивании поршня объём внутри шприца увеличивается, а давление может стать ниже внешнего. Разность давлений помогает жидкости поступать внутрь. При нажатии давление повышается, и жидкость выходит наружу.','Используй чистый учебный шприц без иглы: набери немного воды из стакана и выпусти обратно. Не используй его для медицинских процедур.','Жидкость перемещается под действием разности давлений.'],
['archimedes','🛟','Почему спасательный круг держится на воде','Давление и плавание','Архимедова сила','На погружённую часть круга действует давление воды. На нижние участки оно больше, чем на верхние, поэтому результирующая сила направлена вверх. Архимедова сила равна весу вытесненной воды. В равновесии она уравновешивает вес круга и поддерживаемого им человека.','Сравни в тазу с водой закрытую пустую пластиковую бутылку и такую же бутылку, заполненную водой. Не проводи опыт рядом с глубоким водоёмом.','Плавающее тело вытесняет столько жидкости, чтобы выталкивающая сила могла уравновесить его вес.'],
['hydraulic','🏗','Как работает гидравлический подъёмник','Давление','Закон Паскаля','В замкнутой системе внешнее давление передаётся жидкостью по всем направлениям. На поршне большей площади возникает большая сила, поскольку F = pS. Выигрыш в силе сопровождается проигрышем в расстоянии: малый поршень проходит больший путь.','Нарисуй два соединённых цилиндра разной площади и стрелками покажи передачу давления и направление движения поршней.','Гидравлическое устройство позволяет получить выигрыш в силе, но не создаёт дополнительную работу.']
];
function lifePage(){return '<h1 class="page-title">Физика в жизни</h1><p class="page-intro">Физика объясняет привычные вещи, работу техники, процессы в природе и медицинские приборы. Выбирай ситуацию, изучай механизм и проводи безопасное мини-наблюдение.</p><div class="section-head"><div><h2>Открой физику вокруг себя</h2><p>'+lifeStories.length+' исследовательских историй</p></div></div><div class="content-grid">'+lifeStories.map(function(x){return '<article class="content-card"><div class="article-visual">'+x[1]+'</div><span class="tag">'+x[3]+'</span><h3>'+x[2]+'</h3><p>'+x[4]+'</p><button class="text-link" data-life="'+x[0]+'">Исследовать →</button></article>'}).join('')+'</div>';}
