function lifeDetailPage(id){var x=lifeStories.find(function(item){return item[0]===id});if(!x)return lifePage();var keyMessages={light:'Мы видим частицы в луче благодаря рассеянию света.',cooling:'Тепло самопроизвольно передаётся от более тёплого тела к более холодному.',window:'Конденсация — переход водяного пара в жидкость при охлаждении.',bus:'Инерция — свойство тела сохранять состояние покоя или равномерного прямолинейного движения.',wind:'Ветер — направленное движение воздушных масс.',pressure:'При одной и той же силе большая площадь опоры создаёт меньшее давление.',sound:'Звук возникает при колебаниях источника и распространяется в упругой среде.',friction:'Трение помогает тормозить, но сопровождается нагреванием и износом.',medicine:'Тонометр использует физические принципы измерения давления; результат зависит от правильной процедуры.',syringe:'Жидкость перемещается под действием разности давлений.',archimedes:'Плавающее тело вытесняет столько жидкости, чтобы выталкивающая сила могла уравновесить его вес.',hydraulic:'Гидравлическое устройство позволяет получить выигрыш в силе, но не создаёт дополнительную работу.'};return '<button class="text-link" data-go="life">← Ко всем историям</button><div class="lesson-hero"><span class="tag">Физика в жизни · '+x[3]+'</span><h1 class="page-title">'+x[2]+'</h1><p class="page-intro">'+x[4]+'</p></div>'+lifeVisual(id)+'<section class="lesson-section"><span class="tag">01 · Физическое явление</span><h2>'+x[5]+'</h2><p>'+x[6]+'</p></section><section class="lesson-section"><span class="tag">02 · Попробуй сам</span><h2>Мини-наблюдение</h2><p>'+x[7]+'</p></section><div class="lesson-callout"><strong>Главная мысль:</strong> '+keyMessages[id]+'</div><div class="hero-actions"><button class="primary-btn" data-go="life">Выбрать другую историю</button></div>';}
function simplePage(){return `<h1 class="page-title">Объясни просто</h1><p class="page-intro">Выберите физическое понятие — и разберём его в трёх слоях: простыми словами, на бытовом примере и с научным объяснением.</p><div class="simple-search"><input id="simple-query" placeholder="Например: инерция, давление, ток…"><button class="primary-btn" id="simple-search-btn">Найти</button></div><div id="simple-results" class="content-grid">${["Инерция","Давление","Сила трения","Электрический ток","Диффузия","Сила Архимеда"].map(x=>`<button class="content-card" data-concept="${x}"><h3>${x}</h3><p>Открыть объяснение в трёх слоях →</p></button>`).join("")}</div>`}
const concepts={"инерция":["Инерция — это свойство тела сохранять свою скорость, если на него не действуют другие тела или их действие скомпенсировано.","Когда автобус резко тормозит, пассажир наклоняется вперёд: его тело стремится продолжать прежнее движение.","В инерциальной системе отсчёта тело сохраняет состояние покоя или равномерного прямолинейного движения при нулевой равнодействующей сил."],"давление":["Давление показывает, насколько сильно сила действует на единицу площади поверхности.","Острый каблук оказывает большее давление на пол, чем широкая подошва при одинаковой силе тяжести.","Давление определяется отношением перпендикулярной составляющей силы к площади поверхности: p = F/S."]}
function showConcept(name){let c=concepts[name.toLowerCase()]||[`«${name}» — физическое понятие, которое описывает определённое свойство или явление природы.`,`Найдём пример из повседневной жизни и посмотрим, где с ним можно встретиться.`,`Научное определение, формулы и обозначения будут добавлены после методической проверки соответствующей темы.`];document.getElementById("simple-results").innerHTML=`<article class="content-card"><span class="tag">1 · Простыми словами</span><h3>${name}</h3><p>${c[0]}</p></article><article class="content-card"><span class="tag">2 · На примере</span><h3>Где встречается?</h3><p>${c[1]}</p></article><article class="content-card"><span class="tag">3 · Научно</span><h3>Физическое объяснение</h3><p>${c[2]}</p></article>`}
function searchSimple(){const q=document.getElementById("simple-query").value.trim();if(q)showConcept(q)}
function tasksPage(){return `<h1 class="page-title">Решение задач</h1><p class="page-intro">Тренируйтесь решать физические задачи по понятному алгоритму. Каждый шаг должен объяснять не только вычисление, но и физический смысл.</p><div class="content-card"><span class="tag">Демонстрационная задача · Механика</span><h3>Тележка движется под действием силы 12 Н. Её масса — 3 кг. Найдите ускорение.</h3><div class="lesson-list"><div class="lesson-row"><div><strong>Дано</strong><small>F = 12 Н; m = 3 кг</small></div></div><div class="lesson-row"><div><strong>Найти</strong><small>a — ускорение тележки</small></div></div><div class="lesson-row"><div><strong>Формула</strong><small>a = F / m, где F — равнодействующая сила, m — масса.</small></div></div><div class="lesson-row"><div><strong>Вычисление</strong><small>a = 12 Н / 3 кг = 4 м/с²</small></div></div></div><div class="result-box" style="margin-top:14px">Ответ<strong>4 м/с²</strong>Ускорение тележки равно четырём метрам на секунду в квадрате.</div></div><div class="section-head"><div><h2>Попробуй самостоятельно</h2><p>Введи ответ для следующей задачи</p></div></div><div class="content-card"><h3>На тело массой 2 кг действует сила 10 Н. Чему равно ускорение?</h3><div class="simple-search"><input id="task-answer" type="number" placeholder="Ответ в м/с²"><button class="primary-btn" id="task-check">Проверить</button></div><p id="task-feedback" class="empty-note">Используй связь ускорения, силы и массы.</p></div>`}
function bindTask(){document.getElementById("task-check").addEventListener("click",()=>{let v=Number(document.getElementById("task-answer").value);document.getElementById("task-feedback").textContent=v===5?"Верно! a = 10 / 2 = 5 м/с².":"Пока неверно. Подумай, на какую величину нужно разделить силу."})}
function testsPage(){return `<h1 class="page-title">Проверка знаний</h1><p class="page-intro">Короткая проверка поможет понять, насколько хорошо усвоены основные идеи темы.</p><div class="content-card"><span class="tag">Мини-тест · Механика</span><h3>Что произойдёт с ускорением тела, если равнодействующая сила увеличится в 2 раза, а масса останется прежней?</h3><div class="quiz-options"><label><input type="radio" name="quiz" value="a"> Уменьшится в 2 раза</label><label><input type="radio" name="quiz" value="b"> Не изменится</label><label><input type="radio" name="quiz" value="c"> Увеличится в 2 раза</label></div><button class="primary-btn" id="quiz-check">Проверить ответ</button><p id="quiz-feedback" class="empty-note">Выбери один вариант ответа.</p></div>`}
function bindQuiz(){document.getElementById("quiz-check").addEventListener("click",()=>{const v=document.querySelector('input[name="quiz"]:checked');document.getElementById("quiz-feedback").textContent=!v?"Сначала выбери вариант.":v.value==="c"?"Верно! При неизменной массе ускорение прямо пропорционально равнодействующей силе.":"Не совсем. Вспомни, как ускорение зависит от силы при постоянной массе."})}
function glossaryPage(){const terms=[["Ускорение","Физическая величина, показывающая, как быстро изменяется скорость тела."],["Сила","Векторная физическая величина — мера взаимодействия тел."],["Масса","Физическая величина, характеризующая инертные и гравитационные свойства тела."],["Давление","Физическая величина, равная отношению силы давления к площади поверхности."],["Энергия","Физическая величина, характеризующая способность системы совершать работу."]];return `<h1 class="page-title">Словарь физики</h1><p class="page-intro">Ключевые понятия, обозначения и единицы измерения. Словарь будет расширяться вместе с учебной программой.</p><div class="content-card">${terms.map(t=>`<div class="glossary-term"><strong>${t[0]}</strong><p>${t[1]}</p></div>`).join("")}</div>`}
function progressPage(){return `<h1 class="page-title">Мой прогресс</h1><p class="page-intro">Здесь ученик сможет видеть пройденные темы, результаты тестов и материалы, к которым стоит вернуться.</p><div class="progress-panel"><div class="progress-ring"><span>${Math.min(100,Math.round(completed.length/25*100))}%</span></div><div><strong>Пройдено уроков: ${completed.length}</strong><p>Данные этого прототипа сохраняются на устройстве.</p></div></div><div class="section-head"><div><h2>Завершённые уроки</h2></div></div>${completed.length?`<div class="lesson-list">${completed.map(x=>`<div class="lesson-row"><span class="lesson-number">✓</span><strong>${x}</strong></div>`).join("")}</div>`:`<div class="content-card"><h3>Пока нет завершённых уроков</h3><p>Откройте школьную программу и отметьте первый урок как пройденный.</p><button class="primary-btn" data-go="program">Перейти к программе</button></div>`}`}
document.addEventListener("click",e=>{
 const labOpen=e.target.closest("[data-lab-open]");if(labOpen){const catalog=document.getElementById("lab-catalog"),detail=document.getElementById("lab-detail"),target=document.getElementById(labOpen.dataset.labOpen);if(catalog&&detail&&target){catalog.hidden=true;detail.hidden=false;detail.querySelectorAll(".simulator,.molecule-lab").forEach(el=>el.hidden=el!==target);target.hidden=false;window.scrollTo({top:0,behavior:"smooth"});}return;}
 if(e.target.closest("[data-lab-back]")){const catalog=document.getElementById("lab-catalog"),detail=document.getElementById("lab-detail");if(catalog&&detail){detail.hidden=true;catalog.hidden=false;detail.querySelectorAll(".simulator,.molecule-lab").forEach(el=>el.hidden=false);window.scrollTo({top:0,behavior:"smooth"});}return;}
 const observation=e.target.closest("[data-observation]");
 if(observation){observation.classList.toggle("revealed");return}
 if(e.target.closest("#lesson-quiz-check")){const lesson=window.IMPULS_LESSONS_7?.[document.querySelector(".lesson-hero h1")?.textContent];const selected=document.querySelector('input[name="intro-quiz"]:checked');const out=document.getElementById("lesson-quiz-result");if(!selected){out.textContent="Выбери вариант ответа.";return}out.textContent=Number(selected.value)===lesson.correct?"Верно! Ты правильно понял основную идею.":"Попробуй ещё раз. Вернись к главной мысли урока и проверь свой выбор.";return}
 if(e.target.closest("#complete-lesson")){const title=document.querySelector(".lesson-hero h1")?.textContent;if(title&&!completed.includes(title)){completed.push(title);localStorage.setItem("impuls-completed",JSON.stringify(completed));}e.target.textContent="Урок сохранён ✓";return}const go=e.target.closest("[data-go]");if(go){setPage(go.dataset.go);return}const grade=e.target.closest("[data-grade]");if(grade){currentGrade=Number(grade.dataset.grade);setPage("program");return}const startBrownian=e.target.closest("[data-start-brownian]");if(startBrownian){pageContent.innerHTML=brownianPage();breadcrumbs.textContent="Квест · Броуновское движение";bindBrownian();window.scrollTo(0,0);return}const startInertia=e.target.closest("[data-start-inertia]");if(startInertia){pageContent.innerHTML=inertiaPage();breadcrumbs.textContent="Квест · Инерция";bindInertia();window.scrollTo(0,0);return}const startQuest=e.target.closest("[data-start-diffusion]");if(startQuest){pageContent.innerHTML=diffusionPage();breadcrumbs.textContent="Квест · Диффузия";bindDiffusion();return}const life=e.target.closest("[data-life]");if(life){pageContent.innerHTML=lifeDetailPage(life.dataset.life);breadcrumbs.textContent="Физика в жизни";window.scrollTo(0,0);return}const lesson=e.target.closest("[data-lesson]");if(lesson){pageContent.innerHTML=lessonPage(lesson.dataset.lesson);breadcrumbs.textContent="Урок";window.scrollTo(0,0);return}const concept=e.target.closest("[data-concept]");if(concept)showConcept(concept.dataset.concept)});
const menuToggle=document.getElementById("menu-toggle");
const menuBackdrop=document.getElementById("sidebar-backdrop");
function openMobileMenu(){sidebar.classList.add("open");document.body.classList.add("menu-open");menuToggle.setAttribute("aria-expanded","true");}
function closeMobileMenu(){sidebar.classList.remove("open");document.body.classList.remove("menu-open");menuToggle.setAttribute("aria-expanded","false");}
menuToggle.addEventListener("click",()=>sidebar.classList.contains("open")?closeMobileMenu():openMobileMenu());
document.getElementById("menu-close").addEventListener("click",closeMobileMenu);
menuBackdrop.addEventListener("click",closeMobileMenu);
document.querySelectorAll("button[data-page]").forEach(button=>{
 button.addEventListener("click",event=>{
  event.preventDefault();
  const destination=button.getAttribute("data-page");
  if(destination && pageNames[destination]) setPage(destination);
 });
});
document.addEventListener("keydown",e=>{if(e.key==="Escape")closeMobileMenu();});

document.getElementById("search-toggle").addEventListener("click",()=>{document.getElementById("search-row").classList.toggle("hidden");document.getElementById("search-input").focus()});
document.getElementById("search-submit").addEventListener("click",()=>{const q=document.getElementById("search-input").value.trim();if(!q)return;setPage("simple");document.getElementById("simple-query").value=q;showConcept(q)});
if("serviceWorker" in navigator && location.protocol!=="file:"){window.addEventListener("load",()=>navigator.serviceWorker.register("./sw.js").catch(()=>{}))}
function connection(){const el=document.getElementById("connection-status");el.textContent=navigator.onLine?"Онлайн · офлайн-кэш включён":"Офлайн · доступны сохранённые материалы";}window.addEventListener("online",connection);window.addEventListener("offline",connection);connection();
setPage("home");
